        CmdName::Completions => include_str!("data/help/completions_short.txt"),
        CmdName::Help => include_str!("data/help/help_help.txt"),
        CmdName::Root => include_str!("data/help/main_short.txt"),
    }
}

fn parse_color(v: &str, cmd: CmdName) -> Result<ColorChoice, CliError> {
    match v {
        "auto" => Ok(ColorChoice::Auto),
        "never" => Ok(ColorChoice::Never),
        "always" => Ok(ColorChoice::Always),
        other => {
            let mut msg = format!(
                "invalid value '{}' for '--color <COLOR>'\n  [possible values: auto, never, always]",
                other,
            );
            if let Some(sim) = find_similar(other, &["auto","never","always"]) {
                msg.push_str(&format!("\n\n  tip: a similar value exists: '{}'", sim));
            }
            Err(CliError::new(msg, cmd))
        }
    }
}

fn color_missing_value(cmd: CmdName) -> CliError {
    CliError::new(
        "a value is required for '--color <COLOR>' but none was supplied\n  [possible values: auto, never, always]",
        cmd,
    )
}

// Helper extension on CliError so we can stash a raw rendering.
impl CliError {
    pub fn with_raw(mut self, raw: &'static str) -> Self {
        self.message = String::new();
        self.usage_cmd = CmdName::Root; // placeholder
        // We store the raw text in an unusual way: temporarily.
        RAW_HOLDER.with(|c| c.replace(Some(raw)));
        self
    }
    pub fn is_raw(&self) -> bool { RAW_HOLDER.with(|c| c.borrow().is_some()) }
    pub fn raw_text(&self) -> Option<&'static str> { RAW_HOLDER.with(|c| *c.borrow()) }
}

thread_local! {
    static RAW_HOLDER: std::cell::RefCell<Option<&'static str>> = std::cell::RefCell::new(None);
}
