/// An error that we want to render in clap's style.
#[derive(Debug)]
pub struct CliError {
    pub message: String,
    pub usage_cmd: CmdName,
    pub hint_only: bool, // if true, don't include "For more information, try '--help'." line
}

impl CliError {
    pub fn new(message: impl Into<String>, usage_cmd: CmdName) -> Self {
        Self {
            message: message.into(),
            usage_cmd,
            hint_only: false,
        }
    }

    pub fn print_and_exit(&self, bin: &str) -> ExitCode {
        eprint!("{}", self.render(bin));
        ExitCode::from(2)
    }

    pub fn render(&self, bin: &str) -> String {
        let usage = self.usage_cmd.usage(bin);
        let mut out = format!("error: {}\n\nUsage: {usage}\n\n", self.message);
        if !self.hint_only {
            out.push_str("For more information, try '--help'.\n");
        }
        out
    }
}

// ---- Similarity hint (Levenshtein-like) used by clap for "tip: a similar value ..." ----
fn damerau_levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (m, n) = (a.len(), b.len());
    if m == 0 { return n; }
    if n == 0 { return m; }
    let mut d = vec![vec![0usize; n + 1]; m + 1];
    for i in 0..=m { d[i][0] = i; }
    for j in 0..=n { d[0][j] = j; }
    for i in 1..=m {
        for j in 1..=n {
            let cost = if a[i-1] == b[j-1] { 0 } else { 1 };
            d[i][j] = *[
                d[i-1][j] + 1,
                d[i][j-1] + 1,
                d[i-1][j-1] + cost,
            ].iter().min().unwrap();
            if i > 1 && j > 1 && a[i-1] == b[j-2] && a[i-2] == b[j-1] {
                d[i][j] = d[i][j].min(d[i-2][j-2] + 1);
            }
        }
    }
    d[m][n]
}

fn find_similar<'a>(input: &str, candidates: &'a [&'a str]) -> Option<&'a str> {
    let threshold = 3;
    let mut best: Option<(&str, usize)> = None;
    for cand in candidates {
        let d = damerau_levenshtein(&input.to_lowercase(), &cand.to_lowercase());
        if d < threshold {
            match best {
                Some((_, b)) if b <= d => {}
                _ => best = Some((*cand, d)),
            }
        }
    }
    best.map(|(c, _)| c)
}

/// Top-level argument parse. Returns an Action to execute or an error to render.
pub fn parse(bin: &str, args: &[String]) -> Result<Action, CliError> {
    // First pass: separate global options from subcommand.
    let mut globals = GlobalOpts::default();
    let mut i = 0;
    let mut pos_args: Vec<String> = Vec::new();
    let mut end_of_opts = false;

    while i < args.len() {
        let arg = &args[i];
        if end_of_opts {
            pos_args.push(arg.clone());
            i += 1;
            continue;
        }
        match arg.as_str() {
            "--" => { end_of_opts = true; i += 1; }
            "--help" => return Ok(Action::PrintHelpStdout { text: include_str!("data/help/main_long.txt") }),
            "-h" => return Ok(Action::PrintHelpStdout { text: include_str!("data/help/main_short.txt") }),
            "-V" | "--version" => return Ok(Action::PrintVersion),
            "-v" | "--verbose" => { globals.verbose += 1; i += 1; }
            s if s.starts_with("-v") && s.len() > 2 && s.chars().skip(1).all(|c| c == 'v') => {
                globals.verbose += (s.len() - 1) as u32;
                i += 1;
            }
            "--color" => {
                if i + 1 >= args.len() {
                    return Err(color_missing_value(CmdName::Root));
                }
                globals.color = parse_color(&args[i+1], CmdName::Root)?;
                i += 2;
            }
            s if s.starts_with("--color=") => {
                globals.color = parse_color(&s[8..], CmdName::Root)?;
                i += 1;
            }
            "-c" | "--config" => {
                if i + 1 >= args.len() {
                    return Err(CliError::new(
                        "a value is required for '--config <CONFIG>' but none was supplied",
                        CmdName::Root,
                    ));
                }
                globals.config = Some(args[i+1].clone());
                i += 2;
            }
            s if s.starts_with("--config=") => {
                globals.config = Some(s[9..].to_string());
                i += 1;
            }
            "-p" | "--profile" => {
                if i + 1 >= args.len() {
                    return Err(CliError::new(
                        "a value is required for '--profile <PROFILE>' but none was supplied",
                        CmdName::Root,
                    ));
                }
                globals.profile = Some(args[i+1].clone());
                i += 2;
            }
            s if s.starts_with("--profile=") => {
                globals.profile = Some(s[10..].to_string());
                i += 1;
            }
            s if s.starts_with("--") => {
                return Err(CliError::new(
                    format!("unexpected argument '{}' found", s),
                    CmdName::Root,
                ));
            }
            s if s.starts_with('-') && s.len() > 1 && !s.starts_with("--") => {
                return Err(CliError::new(
                    format!("unexpected argument '{}' found", s),
                    CmdName::Root,
                ));
            }
            _ => {
                // First positional = subcommand
                pos_args.push(arg.clone());
                i += 1;
                // Remaining args are passed to subcommand as-is.
                while i < args.len() {
                    pos_args.push(args[i].clone());
                    i += 1;
                }
            }
        }
    }

    if pos_args.is_empty() {
        // No subcommand → DaemonRequired (which triggers "config not found").
        return Ok(Action::DaemonRequired { globals });
    }

    // Check if the first positional looks like a subcommand. If the user
    // passed `-- <something>` and `something` matches a known subcommand,
    // clap emits a tip message.
    let sub = pos_args[0].clone();
    let rest: Vec<String> = pos_args[1..].to_vec();

    if end_of_opts && SUBCOMMANDS.iter().any(|c| *c == sub) {
        // The only way end_of_opts can be true and pos_args populated is `-- <cmd>`.
        let mut err = CliError::new(
            format!("unexpected argument '{}' found", sub),
            CmdName::Root,
        );
        err.message = format!(
            "unexpected argument '{}' found\n\n  tip: subcommand '{}' exists; to use it, remove the '--' before it",
            sub, sub,
        );
        return Err(err);
    }

    parse_subcommand(&sub, &rest, globals)
}

const SUBCOMMANDS: &[&str] = &[
    "add","remove","switch","stash","enqueue","start","restart","pause","kill",
    "send","edit","env","group","status","log","follow","wait","clean","reset",
    "shutdown","parallel","completions","help",
];

fn parse_subcommand(sub: &str, rest: &[String], globals: GlobalOpts) -> Result<Action, CliError> {
    match sub {
        "add"          => parse_trivial(CmdName::Add, rest, globals),
        "remove"       => parse_trivial(CmdName::Remove, rest, globals),
        "switch"       => parse_trivial(CmdName::Switch, rest, globals),
        "stash"        => parse_trivial(CmdName::Stash, rest, globals),
        "enqueue"      => parse_trivial(CmdName::Enqueue, rest, globals),
        "start"        => parse_trivial(CmdName::Start, rest, globals),
        "restart"      => parse_trivial(CmdName::Restart, rest, globals),
        "pause"        => parse_trivial(CmdName::Pause, rest, globals),
        "kill"         => parse_trivial(CmdName::Kill, rest, globals),
        "send"         => parse_trivial(CmdName::Send, rest, globals),
        "edit"         => parse_trivial(CmdName::Edit, rest, globals),
        "env"          => parse_env(rest, globals),
        "group"        => parse_group(rest, globals),
        "status"       => parse_trivial(CmdName::Status, rest, globals),
        "log"          => parse_trivial(CmdName::Log, rest, globals),
        "follow"       => parse_trivial(CmdName::Follow, rest, globals),
        "wait"         => parse_trivial(CmdName::Wait, rest, globals),
        "clean"        => parse_trivial(CmdName::Clean, rest, globals),
        "reset"        => parse_trivial(CmdName::Reset, rest, globals),
        "shutdown"     => parse_trivial(CmdName::Shutdown, rest, globals),
        "parallel"     => parse_trivial(CmdName::Parallel, rest, globals),
        "completions"  => parse_completions(rest),
        "help"         => parse_help(rest),
        other => {
            let mut err = CliError::new(
                format!("unrecognized subcommand '{}'", other),
                CmdName::Root,
            );
            if let Some(sim) = find_similar(other, SUBCOMMANDS) {
                err.message = format!(
                    "unrecognized subcommand '{}'\n\n  tip: a similar subcommand exists: '{}'",
                    other, sim,
                );
            }
            Err(err)
        }
    }
}

/// A "trivial" subcommand: we don't actually need to fully parse its options.
/// We do a minimal check for --help, then return DaemonRequired for anything
/// else. Args that wouldn't parse cause a runtime error anyway.
fn parse_trivial(cmd: CmdName, rest: &[String], globals: GlobalOpts) -> Result<Action, CliError> {
    // Check for --help / -h anywhere in the args (clap honours it globally).
    for (idx, a) in rest.iter().enumerate() {
        if a == "--" { break; }
        if a == "--help" {
            return Ok(Action::PrintHelpStdout { text: long_help(cmd) });
        }
        if a == "-h" {
            return Ok(Action::PrintHelpStdout { text: short_help(cmd) });
        }
        let _ = idx;
    }
    // Minimal validation for a few commands.
    match cmd {
        CmdName::Remove => {
            let positional = filter_positional(rest);
            if positional.is_empty() {
                return Err(CliError::new(
                    "the following required arguments were not provided:\n  <TASK_IDS>...",
                    cmd,
                ));
            }
            // Validate integers
            for p in &positional {
                if p.parse::<i64>().is_err() {
                    return Err(CliError::new(
                        format!("invalid value '{}' for '<TASK_IDS>...': invalid digit found in string", p),
                        cmd,
                    ));
                }
            }
        }
        CmdName::Switch => {
            let positional = filter_positional(rest);
            if positional.len() < 2 {
                let missing = if positional.is_empty() {
                    "  <TASK_ID_1>\n  <TASK_ID_2>"
                } else {
                    "  <TASK_ID_2>"
                };
                return Err(CliError::new(
                    format!("the following required arguments were not provided:\n{}", missing),
                    cmd,
                ));
            }
            if positional.len() > 2 {
                return Err(CliError::new(
                    format!("unexpected argument '{}' found", positional[2]),
                    cmd,
                ));
            }
            for (i, p) in positional.iter().enumerate() {
                let name = if i == 0 { "<TASK_ID_1>" } else { "<TASK_ID_2>" };
                if p.parse::<i64>().is_err() {
                    return Err(CliError::new(
                        format!("invalid value '{}' for '{}': invalid digit found in string", p, name),
                        cmd,
                    ));
                }
            }
        }
        CmdName::Send => {
            let positional = filter_positional(rest);
            if positional.len() < 2 {
                let missing = if positional.is_empty() {
                    "  <TASK_ID>\n  <INPUT>"
                } else {
                    "  <INPUT>"
                };
                return Err(CliError::new(
                    format!("the following required arguments were not provided:\n{}", missing),
                    cmd,
                ));
            }
            if positional.len() > 2 {
                return Err(CliError::new(
                    format!("unexpected argument '{}' found", positional[2]),
                    cmd,
                ));
            }
            if positional[0].parse::<i64>().is_err() {
                return Err(CliError::new(
                    format!("invalid value '{}' for '<TASK_ID>': invalid digit found in string", positional[0]),
                    cmd,
                ));
            }
        }
        CmdName::Add => {
            let positional = filter_positional(rest);
            if positional.is_empty() {
                return Err(CliError::new(
                    "the following required arguments were not provided:\n  <COMMAND>...",
                    cmd,
                ));
            }
        }
        _ => {}
    }
    Ok(Action::DaemonRequired { globals })
}

fn filter_positional(args: &[String]) -> Vec<String> {
    // Skip anything that looks like an option (and its value when needed).
    // Keep behavior simple: anything not starting with - is positional.
    // Flags that take values:
    let value_flags: &[&str] = &[
        "-w","--working-directory","-d","--delay","-g","--group","-a","--after",
        "-o","--priority","-l","--label","--color","-c","--config","-p","--profile",
        "-s","--signal","--status","-l","--lines","--groups","--failed-in-group",
    ];
    let mut out = Vec::new();
    let mut i = 0;
    let mut end = false;
    while i < args.len() {
        let a = &args[i];
        if end {
            out.push(a.clone());
            i += 1;
            continue;
        }
        if a == "--" { end = true; i += 1; continue; }
        if a.starts_with("--") && a.contains('=') {
            // --key=val, just skip
            i += 1;
            continue;
        }
        if value_flags.contains(&a.as_str()) {
            i += 2;
            continue;
        }
        if a.starts_with('-') && a != "-" {
            // boolean flag
            i += 1;
            continue;
        }
        out.push(a.clone());
        i += 1;
    }
    out
}

fn parse_env(rest: &[String], globals: GlobalOpts) -> Result<Action, CliError> {
    // Check --help/-h on the env command itself.
    for a in rest {
        if a == "--help" || a == "-h" {
            return Ok(Action::PrintHelpStdout { text: include_str!("data/help/env_short.txt") });
        }
    }
    if rest.is_empty() {
        // Per clap: print help to stderr, exit 2.
        return Err(CliError {
            message: String::new(),
            usage_cmd: CmdName::Env,
            hint_only: true,
        }.with_raw(include_str!("data/help/env_short.txt")));
    }
    let sub = &rest[0];
    let sub_rest: Vec<String> = rest[1..].to_vec();
    match sub.as_str() {
        "set" => parse_trivial(CmdName::EnvSet, &sub_rest, globals),
        "unset" => parse_trivial(CmdName::EnvUnset, &sub_rest, globals),
        "help" => parse_help_nested(CmdName::Env, &sub_rest),
        other => {
            let mut err = CliError::new(
                format!("unrecognized subcommand '{}'", other),
                CmdName::Env,
            );
            let subs = &["set", "unset", "help"];
            if let Some(sim) = find_similar(other, subs) {
                err.message = format!(
                    "unrecognized subcommand '{}'\n\n  tip: a similar subcommand exists: '{}'",
                    other, sim,
                );
            }
            Err(err)
        }
    }
}

fn parse_group(rest: &[String], globals: GlobalOpts) -> Result<Action, CliError> {
    for a in rest {
        if a == "--help" {
            return Ok(Action::PrintHelpStdout { text: include_str!("data/help/group_long.txt") });
        }
        if a == "-h" {
            return Ok(Action::PrintHelpStdout { text: include_str!("data/help/group_short.txt") });
        }
    }
    // find first non-option arg
    let mut idx = 0;
    let value_flags: &[&str] = &["-p","--parallel"];
    while idx < rest.len() {
        let a = &rest[idx];
        if a == "-j" || a == "--json" {
            idx += 1;
            continue;
        }
        if value_flags.contains(&a.as_str()) {
            idx += 2;
            continue;
        }
        if a.starts_with('-') && a != "-" {
            idx += 1;
            continue;
        }
        break;
    }
    if idx >= rest.len() {
        return Ok(Action::DaemonRequired { globals });
    }
    let sub = rest[idx].clone();
    let sub_rest: Vec<String> = rest[idx+1..].to_vec();
    match sub.as_str() {
        "add" => parse_trivial(CmdName::GroupAdd, &sub_rest, globals),
        "remove" => parse_trivial(CmdName::GroupRemove, &sub_rest, globals),
        "help" => parse_help_nested(CmdName::Group, &sub_rest),
        other => {
            let mut err = CliError::new(
                format!("unrecognized subcommand '{}'", other),
                CmdName::Group,
            );
            let subs = &["add", "remove", "help"];
            if let Some(sim) = find_similar(other, subs) {
                err.message = format!(
                    "unrecognized subcommand '{}'\n\n  tip: a similar subcommand exists: '{}'",
                    other, sim,
                );
            }
            Err(err)
        }
    }
}

fn parse_completions(rest: &[String]) -> Result<Action, CliError> {
    for a in rest {
        if a == "--help" {
            return Ok(Action::PrintHelpStdout { text: include_str!("data/help/completions_long.txt") });
        }
        if a == "-h" {
            return Ok(Action::PrintHelpStdout { text: include_str!("data/help/completions_short.txt") });
        }
    }
    let pos: Vec<&String> = rest.iter().filter(|a| !a.starts_with('-') || a.as_str() == "-").collect();
    if pos.is_empty() {
        return Err(CliError::new(
            "the following required arguments were not provided:\n  <SHELL>",
            CmdName::Completions,
        ));
    }
    if pos.len() > 2 {
        return Err(CliError::new(
            format!("unexpected argument '{}' found", pos[2]),
            CmdName::Completions,
        ));
    }
    let shell_name = pos[0].as_str();
    let shell = match shell_name {
        "bash" => Shell::Bash,
        "elvish" => Shell::Elvish,
        "fish" => Shell::Fish,
        "power-shell" => Shell::PowerShell,
        "zsh" => Shell::Zsh,
        "nushell" => Shell::Nushell,
        other => {
            let candidates = &["bash","elvish","fish","power-shell","zsh","nushell"];
            let mut msg = format!(
                "invalid value '{}' for '<SHELL>'\n  [possible values: bash, elvish, fish, power-shell, zsh, nushell]",
                other,
            );
            if let Some(sim) = find_similar(other, candidates) {
                msg.push_str(&format!("\n\n  tip: a similar value exists: '{}'", sim));
            }
            return Err(CliError::new(msg, CmdName::Completions));
        }
    };
    if pos.len() == 2 {
        return Ok(Action::CompletionsFile { shell, dir: pos[1].clone() });
    }
    Ok(Action::CompletionsOutput { shell })
}

fn parse_help(rest: &[String]) -> Result<Action, CliError> {
    // help <subcommand>
    if rest.is_empty() {
        return Ok(Action::PrintHelpStdout { text: include_str!("data/help/main_long.txt") });
    }
    // Check for any options (none are defined) - allowed through though as positional
    let sub = &rest[0];
    match sub.as_str() {
        "help" => Ok(Action::PrintHelpStdout { text: include_str!("data/help/help_help.txt") }),
        "env" => {
            // help env [sub]
            if rest.len() >= 2 {
                let s = rest[1].as_str();
                return match s {
                    "set" => Ok(Action::PrintHelpStdout { text: long_help(CmdName::EnvSet) }),
                    "unset" => Ok(Action::PrintHelpStdout { text: long_help(CmdName::EnvUnset) }),
                    "help" => Ok(Action::PrintHelpStdout { text: include_str!("data/help/env_help_help.txt") }),
                    other => {
                        let mut err = CliError::new(
                            format!("unrecognized subcommand '{}'", other),
                            CmdName::Env,
                        );
                        if let Some(sim) = find_similar(other, &["set","unset","help"]) {
                            err.message = format!(
                                "unrecognized subcommand '{}'\n\n  tip: a similar subcommand exists: '{}'",
                                other, sim,
                            );
                        }
                        Err(err)
                    }
                };
            }
            Ok(Action::PrintHelpStdout { text: include_str!("data/help/env_long.txt") })
        }
        "group" => {
            if rest.len() >= 2 {
                let s = rest[1].as_str();
                return match s {
                    "add" => Ok(Action::PrintHelpStdout { text: long_help(CmdName::GroupAdd) }),
                    "remove" => Ok(Action::PrintHelpStdout { text: long_help(CmdName::GroupRemove) }),
                    "help" => Ok(Action::PrintHelpStdout { text: include_str!("data/help/group_help_help.txt") }),
                    other => {
                        let mut err = CliError::new(
                            format!("unrecognized subcommand '{}'", other),
                            CmdName::Group,
                        );
                        if let Some(sim) = find_similar(other, &["add","remove","help"]) {
                            err.message = format!(
                                "unrecognized subcommand '{}'\n\n  tip: a similar subcommand exists: '{}'",
                                other, sim,
                            );
                        }
                        Err(err)
                    }
                };
            }
            Ok(Action::PrintHelpStdout { text: include_str!("data/help/group_long.txt") })
        }
        other => {
            if let Some(cmd) = match_top_level_subcommand(other) {
                return Ok(Action::PrintHelpStdout { text: long_help(cmd) });
            }
            let mut err = CliError::new(
                format!("unrecognized subcommand '{}'", other),
                CmdName::Root,
            );
            if let Some(sim) = find_similar(other, SUBCOMMANDS) {
                err.message = format!(
                    "unrecognized subcommand '{}'\n\n  tip: a similar subcommand exists: '{}'",
                    other, sim,
                );
            }
            Err(err)
        }
    }
}

