// Helper extension on CliError so we can stash a raw rendering.
impl CliError {
    pub fn with_raw(mut self, raw: &'static str) -> Self {
        self.message = String::new();
        self.usage_cmd = CmdName::Root; // placeholder
        // We store the raw text in an unusual way: temporarily.
        RAW_HOLDER.with(|c| c.replace(Some(raw)));
        self
    }
    pub fn is_raw(&self) -> bool { RAW_HOLDER.with(|c| c.borrow().is_some()) }
    pub fn raw_text(&self) -> Option<&'static str> { RAW_HOLDER.with(|c| *c.borrow()) }
}

