    "add","remove","switch","stash","enqueue","start","restart","pause","kill",
    "send","edit","env","group","status","log","follow","wait","clean","reset",
    "shutdown","parallel","completions","help",
];

const ENV_SUBS: &[&str] = &["set","unset","help"];
const GROUP_SUBS: &[&str] = &["add","remove","help"];

/// Main entry point: parse argv into an Action.
pub fn parse(args: &[String]) -> Action {
    let mut globals = GlobalOpts::default();
    let mut i = 0;
    let mut saw_double_dash = false;

    while i < args.len() {
        let arg = args[i].clone();
        match arg.as_str() {
            "--" => { saw_double_dash = true; i += 1; break; }
            "--help" => return Action::HelpStdout(CmdName::Root.long_help()),
            "-h" => return Action::HelpStdout(CmdName::Root.short_help()),
            "-V" | "--version" => return Action::PrintVersion,
            "-v" | "--verbose" => { globals.verbose += 1; i += 1; }
            s if s.len() > 2 && &s[0..1] == "-" && &s[1..2] == "v"
                 && s[1..].chars().all(|c| c == 'v') => {
                globals.verbose += (s.len() - 1) as u32;
                i += 1;
            }
            "--color" => {
                let Some(v) = args.get(i + 1) else {
                    return Action::ArgError(ArgError::new(
                        "a value is required for '--color <COLOR>' but none was supplied\n  [possible values: auto, never, always]",
                        CmdName::Root));
                };
                match parse_color(v) {
                    Ok(c) => { globals.color = c; i += 2; }
                    Err(e) => return Action::ArgError(e),
                }
            }
            s if s.starts_with("--color=") => {
                match parse_color(&s[8..]) {
                    Ok(c) => { globals.color = c; i += 1; }
                    Err(e) => return Action::ArgError(e),
                }
            }
            "-c" | "--config" => {
                let Some(v) = args.get(i + 1) else {
                    return Action::ArgError(ArgError::new(
                        "a value is required for '--config <CONFIG>' but none was supplied",
                        CmdName::Root));
                };
                globals.config = Some(v.clone());
                i += 2;
            }
            s if s.starts_with("--config=") => {
                globals.config = Some(s[9..].to_string());
                i += 1;
            }
            s if s.starts_with("-c") && s.len() > 2 && !s.starts_with("--") => {
                globals.config = Some(s[2..].to_string());
                i += 1;
            }
            "-p" | "--profile" => {
                let Some(v) = args.get(i + 1) else {
                    return Action::ArgError(ArgError::new(
                        "a value is required for '--profile <PROFILE>' but none was supplied",
                        CmdName::Root));
                };
                globals.profile = Some(v.clone());
                i += 2;
            }
            s if s.starts_with("--profile=") => {
                globals.profile = Some(s[10..].to_string());
                i += 1;
            }
            s if s.starts_with("-p") && s.len() > 2 && !s.starts_with("--") => {
                globals.profile = Some(s[2..].to_string());
                i += 1;
            }
            s if s.starts_with("--") => {
                return Action::ArgError(ArgError::new(
                    format!("unexpected argument '{}' found", s),
                    CmdName::Root,
                ));
            }
            s if s.starts_with('-') && s.len() > 1 => {
                return Action::ArgError(ArgError::new(
                    format!("unexpected argument '{}' found", s),
                    CmdName::Root,
                ));
            }
            _ => break, // found subcommand
        }
    }

    let rest: Vec<String> = args[i..].to_vec();

    if rest.is_empty() {
        return Action::DaemonRequired(globals);
    }

    let sub = rest[0].clone();

    if saw_double_dash && TOP_SUBCOMMANDS.iter().any(|c| *c == sub.as_str()) {
        return Action::ArgError(ArgError::new(
            format!(
                "unexpected argument '{}' found\n\n  tip: subcommand '{}' exists; to use it, remove the '--' before it",
                sub, sub
            ),
            CmdName::Root,
        ));
    }

    parse_subcommand(&sub, &rest[1..], globals)
}

fn parse_subcommand(sub: &str, rest: &[String], globals: GlobalOpts) -> Action {
    match sub {
        "add"          => parse_trivial(CmdName::Add, rest, globals),
        "remove"       => parse_trivial(CmdName::Remove, rest, globals),
        "switch"       => parse_trivial(CmdName::Switch, rest, globals),
        "stash"        => parse_trivial(CmdName::Stash, rest, globals),
        "enqueue"      => parse_trivial(CmdName::Enqueue, rest, globals),
        "start"        => parse_trivial(CmdName::Start, rest, globals),
        "restart"      => parse_trivial(CmdName::Restart, rest, globals),
        "pause"        => parse_trivial(CmdName::Pause, rest, globals),
        "kill"         => parse_trivial(CmdName::Kill, rest, globals),
        "send"         => parse_trivial(CmdName::Send, rest, globals),
        "edit"         => parse_trivial(CmdName::Edit, rest, globals),
        "env"          => parse_env(rest, globals),
        "group"        => parse_group(rest, globals),
        "status"       => parse_trivial(CmdName::Status, rest, globals),
        "log"          => parse_trivial(CmdName::Log, rest, globals),
        "follow"       => parse_trivial(CmdName::Follow, rest, globals),
        "wait"         => parse_trivial(CmdName::Wait, rest, globals),
        "clean"        => parse_trivial(CmdName::Clean, rest, globals),
        "reset"        => parse_trivial(CmdName::Reset, rest, globals),
        "shutdown"     => parse_trivial(CmdName::Shutdown, rest, globals),
        "parallel"     => parse_trivial(CmdName::Parallel, rest, globals),
        "completions"  => parse_completions(rest),
        "help"         => parse_help(rest),
        other => {
            let mut msg = format!("unrecognized subcommand '{}'", other);
            if let Some(sim) = find_similar(other, TOP_SUBCOMMANDS) {
                msg = format!(
                    "unrecognized subcommand '{}'\n\n  tip: a similar subcommand exists: '{}'",
                    other, sim,
                );
            }
            Action::ArgError(ArgError::new(msg, CmdName::Root))
        }
    }
}

/// For commands that don't need deep semantic validation, we just honour
/// --help / -h and otherwise return DaemonRequired. (The real binary would
/// fail with "Couldn't find a configuration file" at this point anyway.)
fn parse_trivial(cmd: CmdName, rest: &[String], globals: GlobalOpts) -> Action {
    for a in rest {
        if a == "--" { break; }
        if a == "--help" { return Action::HelpStdout(cmd.long_help()); }
        if a == "-h" { return Action::HelpStdout(cmd.short_help()); }
    }
    match cmd {
        CmdName::Remove => {
            let positional = extract_positional(rest, cmd);
            if positional.is_empty() {
                return Action::ArgError(ArgError::new(
                    "the following required arguments were not provided:\n  <TASK_IDS>...",
                    cmd,
                ));
            }
            for p in &positional {
                if p.parse::<i64>().is_err() {
                    return Action::ArgError(ArgError::new(
                        format!("invalid value '{}' for '<TASK_IDS>...': invalid digit found in string", p),
                        cmd,
                    ));
                }
            }
        }
        CmdName::Switch => {
            let positional = extract_positional(rest, cmd);
            if positional.len() < 2 {
                let missing = if positional.is_empty() {
                    "  <TASK_ID_1>\n  <TASK_ID_2>"
                } else {
                    "  <TASK_ID_2>"
                };
                return Action::ArgError(ArgError::new(
                    format!("the following required arguments were not provided:\n{}", missing),
                    cmd,
                ));
            }
            if positional.len() > 2 {
                return Action::ArgError(ArgError::new(
                    format!("unexpected argument '{}' found", positional[2]),
                    cmd,
                ));
            }
            for (idx, p) in positional.iter().enumerate() {
                let name = if idx == 0 { "<TASK_ID_1>" } else { "<TASK_ID_2>" };
                if p.parse::<i64>().is_err() {
                    return Action::ArgError(ArgError::new(
                        format!("invalid value '{}' for '{}': invalid digit found in string", p, name),
                        cmd,
                    ));
                }
            }
        }
        CmdName::Send => {
            let positional = extract_positional(rest, cmd);
            if positional.len() < 2 {
                let missing = if positional.is_empty() {
                    "  <TASK_ID>\n  <INPUT>"
                } else {
                    "  <INPUT>"
                };
                return Action::ArgError(ArgError::new(
                    format!("the following required arguments were not provided:\n{}", missing),
                    cmd,
                ));
            }
            if positional.len() > 2 {
                return Action::ArgError(ArgError::new(
                    format!("unexpected argument '{}' found", positional[2]),
                    cmd,
                ));
            }
            if positional[0].parse::<i64>().is_err() {
                return Action::ArgError(ArgError::new(
                    format!("invalid value '{}' for '<TASK_ID>': invalid digit found in string", positional[0]),
                    cmd,
                ));
            }
        }
        CmdName::Add => {
            let positional = extract_positional(rest, cmd);
            if positional.is_empty() {
                return Action::ArgError(ArgError::new(
                    "the following required arguments were not provided:\n  <COMMAND>...",
                    cmd,
                ));
            }
        }
        CmdName::EnvSet => {
            let positional = extract_positional(rest, cmd);
            if positional.len() < 3 {
                let mut missing = Vec::new();
                if positional.is_empty() { missing.push("  <TASK_ID>"); }
                if positional.len() < 2 { missing.push("  <KEY>"); }
                if positional.len() < 3 { missing.push("  <VALUE>"); }
                return Action::ArgError(ArgError::new(
                    format!("the following required arguments were not provided:\n{}", missing.join("\n")),
                    cmd,
                ));
            }
            if positional.len() > 3 {
                return Action::ArgError(ArgError::new(
                    format!("unexpected argument '{}' found", positional[3]),
                    cmd,
                ));
            }
            if positional[0].parse::<i64>().is_err() {
                return Action::ArgError(ArgError::new(
                    format!("invalid value '{}' for '<TASK_ID>': invalid digit found in string", positional[0]),
                    cmd,
                ));
            }
        }
        CmdName::EnvUnset => {
            let positional = extract_positional(rest, cmd);
            if positional.len() < 2 {
                let mut missing = Vec::new();
                if positional.is_empty() { missing.push("  <TASK_ID>"); }
                if positional.len() < 2 { missing.push("  <KEY>"); }
                return Action::ArgError(ArgError::new(
                    format!("the following required arguments were not provided:\n{}", missing.join("\n")),
                    cmd,
                ));
            }
            if positional.len() > 2 {
                return Action::ArgError(ArgError::new(
                    format!("unexpected argument '{}' found", positional[2]),
                    cmd,
                ));
            }
            if positional[0].parse::<i64>().is_err() {
                return Action::ArgError(ArgError::new(
                    format!("invalid value '{}' for '<TASK_ID>': invalid digit found in string", positional[0]),
                    cmd,
                ));
            }
        }
        CmdName::GroupAdd => {
            let positional = extract_positional(rest, cmd);
            if positional.is_empty() {
                return Action::ArgError(ArgError::new(
                    "the following required arguments were not provided:\n  <NAME>",
                    cmd,
                ));
            }
            if positional.len() > 1 {
                return Action::ArgError(ArgError::new(
                    format!("unexpected argument '{}' found", positional[1]),
                    cmd,
                ));
            }
        }
        CmdName::GroupRemove => {
            let positional = extract_positional(rest, cmd);
            if positional.is_empty() {
                return Action::ArgError(ArgError::new(
                    "the following required arguments were not provided:\n  <NAME>",
                    cmd,
                ));
            }
            if positional.len() > 1 {
                return Action::ArgError(ArgError::new(
                    format!("unexpected argument '{}' found", positional[1]),
                    cmd,
                ));
            }
        }
        _ => {}
    }
    Action::DaemonRequired(globals)
}

/// Return all positional (non-option) arguments, assuming we know which flags take values.
fn extract_positional(args: &[String], cmd: CmdName) -> Vec<String> {
    let value_flags: &[&str] = match cmd {
        CmdName::Add => &["-w","--working-directory","-d","--delay","-g","--group","-a","--after","-o","--priority","-l","--label"],
        CmdName::Stash | CmdName::Enqueue => &["-g","--group","-d","--delay"],
        CmdName::Start | CmdName::Pause => &["-g","--group"],
        CmdName::Restart => &["-g","--failed-in-group"],
        CmdName::Kill => &["-g","--group","-s","--signal"],
        CmdName::Log => &["-g","--group","-l","--lines"],
        CmdName::Follow => &["-l","--lines"],
        CmdName::Wait => &["-g","--group","-s","--status"],
        CmdName::Clean => &["-g","--group"],
        CmdName::Reset => &["-g","--groups"],
        CmdName::Status => &["-g","--group"],
        CmdName::Parallel => &["-g","--group"],
        CmdName::GroupAdd => &["-p","--parallel"],
        _ => &[],
    };
    let bool_flags: &[&str] = &[
        "-e","--escape","-i","--immediate","--follow","-s","--stashed","-p","--print-task-id",
        "-a","--all","-a","--all-failed","-j","--json","-f","--full","-q","--quiet",
        "-k","--in-place","--not-in-place","-w","--wait","-f","--force",
        "--successful-only",
    ];
    let mut out = Vec::new();
    let mut i = 0;
    let mut end = false;
    while i < args.len() {
        let a = &args[i];
        if end { out.push(a.clone()); i += 1; continue; }
        if a == "--" { end = true; i += 1; continue; }
        if a.starts_with("--") && a.contains('=') { i += 1; continue; }
        if value_flags.contains(&a.as_str()) {
            // For some commands the same short flag is a bool vs. value flag;
            // the safe option is to consume the next arg as value.
            i += 2;
            continue;
        }
        if bool_flags.contains(&a.as_str()) {
            i += 1;
            continue;
        }
        if a.starts_with('-') && a != "-" {
            // Unknown option — skip it, don't classify as positional.
            i += 1;
            continue;
        }
        out.push(a.clone());
        i += 1;
    }
    out
}

fn parse_env(rest: &[String], globals: GlobalOpts) -> Action {
    for a in rest {
        if a == "--help" || a == "-h" {
            return Action::HelpStdout(CmdName::Env.long_help());
        }
    }
    if rest.is_empty() {
        // Clap style: print help to stderr, exit 2.
        return Action::HelpStderr(CmdName::Env.long_help());
    }
    let sub = &rest[0];
    let sub_rest: Vec<String> = rest[1..].to_vec();
    match sub.as_str() {
        "set" => parse_trivial(CmdName::EnvSet, &sub_rest, globals),
        "unset" => parse_trivial(CmdName::EnvUnset, &sub_rest, globals),
        "help" => parse_help_env(&sub_rest),
        other => {
            let mut msg = format!("unrecognized subcommand '{}'", other);
            if let Some(sim) = find_similar(other, ENV_SUBS) {
                msg = format!(
                    "unrecognized subcommand '{}'\n\n  tip: a similar subcommand exists: '{}'",
                    other, sim,
                );
            }
            Action::ArgError(ArgError::new(msg, CmdName::Env))
        }
    }
}

fn parse_group(rest: &[String], globals: GlobalOpts) -> Action {
    for a in rest {
        if a == "--help" { return Action::HelpStdout(CmdName::Group.long_help()); }
        if a == "-h" { return Action::HelpStdout(CmdName::Group.short_help()); }
    }
    // Skip top-level group options.
    let mut idx = 0;
    while idx < rest.len() {
        let a = &rest[idx];
        if a == "-j" || a == "--json" { idx += 1; continue; }
        if a.starts_with('-') && a != "-" { idx += 1; continue; } // unknown option
        break;
    }
    if idx >= rest.len() {
        return Action::DaemonRequired(globals);
    }
    let sub = rest[idx].clone();
    let sub_rest: Vec<String> = rest[idx + 1..].to_vec();
    match sub.as_str() {
        "add" => parse_trivial(CmdName::GroupAdd, &sub_rest, globals),
        "remove" => parse_trivial(CmdName::GroupRemove, &sub_rest, globals),
        "help" => parse_help_group(&sub_rest),
        other => {
            let mut msg = format!("unrecognized subcommand '{}'", other);
            if let Some(sim) = find_similar(other, GROUP_SUBS) {
                msg = format!(
                    "unrecognized subcommand '{}'\n\n  tip: a similar subcommand exists: '{}'",
                    other, sim,
                );
            }
            Action::ArgError(ArgError::new(msg, CmdName::Group))
        }
    }
}

fn parse_completions(rest: &[String]) -> Action {
    for a in rest {
        if a == "--help" { return Action::HelpStdout(CmdName::Completions.long_help()); }
        if a == "-h" { return Action::HelpStdout(CmdName::Completions.short_help()); }
    }
    let pos: Vec<String> = rest.iter()
        .filter(|a| !(a.starts_with('-') && a.as_str() != "-"))
        .cloned()
        .collect();
    if pos.is_empty() {
        return Action::ArgError(ArgError::new(
            "the following required arguments were not provided:\n  <SHELL>",
            CmdName::Completions,
        ));
    }
    if pos.len() > 2 {
        return Action::ArgError(ArgError::new(
            format!("unexpected argument '{}' found", pos[2]),
            CmdName::Completions,
        ));
    }
    let shell = match pos[0].as_str() {
        "bash" => Shell::Bash,
        "elvish" => Shell::Elvish,
        "fish" => Shell::Fish,
        "power-shell" => Shell::PowerShell,
        "zsh" => Shell::Zsh,
        "nushell" => Shell::Nushell,
        other => {
            let mut msg = format!(
                "invalid value '{}' for '<SHELL>'\n  [possible values: bash, elvish, fish, power-shell, zsh, nushell]",
                other,
            );
            if let Some(sim) = find_similar(other, &["bash","elvish","fish","power-shell","zsh","nushell"]) {
                msg.push_str(&format!("\n\n  tip: a similar value exists: '{}'", sim));
            }
            return Action::ArgError(ArgError::new(msg, CmdName::Completions));
        }
    };
    if pos.len() == 2 {
        Action::CompletionsFile(shell, pos[1].clone())
    } else {
        Action::CompletionsStdout(shell)
    }
}

fn parse_help(rest: &[String]) -> Action {
    if rest.is_empty() {
        return Action::HelpStdout(CmdName::Root.long_help());
    }
    let sub = rest[0].as_str();
    match sub {
        "help" => Action::HelpStdout(CmdName::Help.long_help()),
        "env" => {
            if rest.len() >= 2 {
                let s = rest[1].as_str();
                return match s {
                    "set" => Action::HelpStdout(CmdName::EnvSet.long_help()),
                    "unset" => Action::HelpStdout(CmdName::EnvUnset.long_help()),
                    "help" => Action::HelpStdout(include_str!("data/help/env_help_help.txt")),
                    other => {
                        let mut msg = format!("unrecognized subcommand '{}'", other);
                        if let Some(sim) = find_similar(other, ENV_SUBS) {
                            msg = format!(
                                "unrecognized subcommand '{}'\n\n  tip: a similar subcommand exists: '{}'",
                                other, sim,
                            );
                        }
                        Action::ArgError(ArgError::new(msg, CmdName::Env))
                    }
                };
            }
            Action::HelpStdout(CmdName::Env.long_help())
        }
        "group" => {
            if rest.len() >= 2 {
                let s = rest[1].as_str();
                return match s {
                    "add" => Action::HelpStdout(CmdName::GroupAdd.long_help()),
                    "remove" => Action::HelpStdout(CmdName::GroupRemove.long_help()),
                    "help" => Action::HelpStdout(include_str!("data/help/group_help_help.txt")),
                    other => {
                        let mut msg = format!("unrecognized subcommand '{}'", other);
                        if let Some(sim) = find_similar(other, GROUP_SUBS) {
                            msg = format!(
                                "unrecognized subcommand '{}'\n\n  tip: a similar subcommand exists: '{}'",
                                other, sim,
                            );
                        }
                        Action::ArgError(ArgError::new(msg, CmdName::Group))
                    }
                };
            }
            Action::HelpStdout(CmdName::Group.long_help())
        }
        other => {
            if let Some(cmd) = match_top_level_subcommand(other) {
                return Action::HelpStdout(cmd.long_help());
            }
            let mut msg = format!("unrecognized subcommand '{}'", other);
            if let Some(sim) = find_similar(other, TOP_SUBCOMMANDS) {
                msg = format!(
                    "unrecognized subcommand '{}'\n\n  tip: a similar subcommand exists: '{}'",
                    other, sim,
                );
            }
            Action::ArgError(ArgError::new(msg, CmdName::Root))
        }
    }
}

fn parse_help_env(rest: &[String]) -> Action {
    if rest.is_empty() {
