fn render_eyre(lines: &[&str], file: &str, line: &str) -> String {
    let mut out = String::new();
    out.push_str("Error: \n");
    for (i, msg) in lines.iter().enumerate() {
        // "   0: \x1b[91m<msg>\x1b[0m"
        out.push_str(&format!("   {}: \x1b[91m{}\x1b[0m\n", i, msg));
    }
    out.push('\n');
    out.push_str("Location:\n");
    out.push_str(&format!(
        "   \x1b[35m{}\x1b[0m:\x1b[35m{}\x1b[0m\n",
        file, line
    ));
    out.push('\n');
    out.push_str("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.\n");
    out.push_str("Run with RUST_BACKTRACE=full to include source snippets.\n");
    out
}

/// Work out which config file path the executable would use based on
/// the supplied --config option / the PUEUE_CONFIG_PATH environment var,
/// falling back to common search locations.
///
/// Returns (Some(path), true) when the user explicitly asked for a path
/// (via --config or PUEUE_CONFIG_PATH); (None, false) otherwise.
pub fn resolved_config(explicit: Option<&str>) -> Result<ResolvedConfig, ConfigProbe> {
    // 1. --config wins, then $PUEUE_CONFIG_PATH.
    let explicit_path = match explicit {
        Some(p) => Some(p.to_string()),
        None => std::env::var("PUEUE_CONFIG_PATH").ok().filter(|s| !s.is_empty()),
    };

    if let Some(p) = &explicit_path {
        let pb = PathBuf::from(p);
        if pb.is_file() {
            return Ok(ResolvedConfig { path: pb, explicit: true });
        } else {
            return Err(ConfigProbe::ExplicitMissing(p.clone()));
        }
    }

    // 2. XDG/standard paths. Only the first-matched candidate is used.
    let mut candidates: Vec<PathBuf> = Vec::new();

    if let Some(home) = std::env::var_os("HOME") {
        let home = Path::new(&home).to_path_buf();
        candidates.push(home.join(".config/pueue/pueue.yml"));
    }
    candidates.push(PathBuf::from("./pueue.yml"));

    for c in &candidates {
        if c.is_file() {
            return Ok(ResolvedConfig { path: c.clone(), explicit: false });
        }
    }
    Err(ConfigProbe::NotFound { tried: candidates })
}

#[derive(Debug)]
pub struct ResolvedConfig {
    pub path: PathBuf,
    pub explicit: bool,
}

#[derive(Debug)]
pub enum ConfigProbe {
    /// User explicitly asked for a config file that doesn't exist.
    ExplicitMissing(String),
    /// No config file found at any of the search paths.
    NotFound { tried: Vec<PathBuf> },
}
