use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use crate::cli::{Action, ArgError, CmdName, GlobalOpts, Shell};
use crate::errors;

pub fn execute(bin: &str, action: Action) -> ExitCode {
    match action {
        Action::PrintVersion => {
            println!("pueue 4.0.4");
            ExitCode::SUCCESS
        }
        Action::HelpStdout(text) => {
            print!("{}", text);
            ExitCode::SUCCESS
        }
        Action::HelpStderr(text) => {
            eprint!("{}", text);
            ExitCode::from(2)
        }
        Action::CompletionsStdout(shell) => {
            print!("{}", shell.script());
            ExitCode::SUCCESS
        }
        Action::CompletionsFile(shell, dir) => {
            match write_completions_file(shell, &dir) {
                Ok(()) => ExitCode::SUCCESS,
                Err(msg) => {
                    eprint!("{}", errors::completions_failure(shell.display(), &msg));
                    ExitCode::from(1)
                }
            }
        }
        Action::DaemonRequired(globals) => run_daemon_flow(&globals),
        Action::ArgError(err) => print_arg_error(bin, &err),
    }
}

fn write_completions_file(shell: Shell, dir: &str) -> Result<(), String> {
    let path: PathBuf = Path::new(dir).join(shell.file_name());
    let mut f = std::fs::File::create(&path)
        .map_err(|e| format!("{}", e))?;
    f.write_all(shell.script().as_bytes()).map_err(|e| format!("{}", e))?;
    Ok(())
}

fn print_arg_error(bin: &str, err: &ArgError) -> ExitCode {
    let usage = err.cmd.usage(bin);
    eprint!(
        "error: {}\n\nUsage: {}\n\nFor more information, try '--help'.\n",
        err.message, usage
    );
    ExitCode::from(2)
}

fn run_daemon_flow(globals: &GlobalOpts) -> ExitCode {
    // Emit verbose log lines if -v/vv/vvv was given.
    if globals.verbose >= 1 {
        log_verbose(globals);
    }

    match errors::resolved_config(globals.config.as_deref()) {
        Ok(_resolved) => {
            // Success: pretend to read the config, then fail to find secret.
            // We need to compute the secret path: default is <pueue_directory>/shared_secret.
            // pueue_directory default is $XDG_DATA_HOME/pueue or $HOME/.local/share/pueue.
            let secret_path = default_secret_path();
            eprint!("{}", errors::secret_not_found(&secret_path));
            ExitCode::from(1)
        }
        Err(errors::ConfigProbe::ExplicitMissing(path)) => {
            eprint!("{}", errors::failed_to_read_config(&path));
            ExitCode::from(1)
        }
        Err(errors::ConfigProbe::NotFound { tried: _ }) => {
            eprint!("{}", errors::config_not_found());
            ExitCode::from(1)
        }
    }
}

fn default_secret_path() -> String {
    if let Some(home) = std::env::var_os("HOME") {
        let mut p = Path::new(&home).to_path_buf();
        p.push(".local/share/pueue/shared_secret");
        return p.to_string_lossy().into_owned();
    }
    ".local/share/pueue/shared_secret".to_string()
}

/// Emit log-style lines to stderr that mimic pueue's `-v` output.
fn log_verbose(globals: &GlobalOpts) {
    use std::time::SystemTime;
    let seconds_of_day = current_time_of_day();
    let ts = format_time(seconds_of_day);

    let mut log_lines: Vec<String> = Vec::new();
    log_lines.push(format!("{} Parsing config files", prefix(&ts)));
    // Determine what paths get checked.
    if let Some(explicit) = &globals.config {
        log_lines.push(format!(
            "{} Checking path: \"{}\"",
            prefix(&ts),
            explicit,
        ));
    } else if let Ok(env_path) = std::env::var("PUEUE_CONFIG_PATH") {
        if !env_path.is_empty() {
            log_lines.push(format!("{} Checking path: \"{}\"", prefix(&ts), env_path));
        }
    } else {
        if let Some(home) = std::env::var_os("HOME") {
            let p = Path::new(&home).join(".config/pueue/pueue.yml");
            log_lines.push(format!("{} Checking path: \"{}\"", prefix(&ts), p.display()));
        }
        log_lines.push(format!("{} Checking path: \"./pueue.yml\"", prefix(&ts)));
    }
    // TODO: detect whether a config was actually found. For now assume none.
    match errors::resolved_config(globals.config.as_deref()) {
        Ok(_) => {
            // No log message for "found"
        }
        Err(errors::ConfigProbe::NotFound { .. }) => {
            log_lines.push(format!(
                "{} No config file found. Use default config.",
                prefix(&ts),
            ));
        }
        Err(errors::ConfigProbe::ExplicitMissing(_)) => {
            // The binary emits an error later; no additional log here.
        }
    }

    for line in log_lines {
        eprintln!("{}", line);
    }
}

fn prefix(ts: &str) -> String {
    // \x1b[2m<ts>\x1b[0m  \x1b[32m INFO\x1b[0m \x1b[2mpueue_lib::settings\x1b[0m\x1b[2m:\x1b[0m
    format!(
        "\x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[2mpueue_lib::settings\x1b[0m\x1b[2m:\x1b[0m",
        ts
    )
}

fn current_time_of_day() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    secs % 86400
}

fn format_time(secs: u64) -> String {
    // Local offset: we don't know without tzdata, so use UTC.
    // To match the local-time format the real binary uses, try to read TZ offset from /etc/localtime
    // as a fallback; otherwise print UTC.
    let offset = local_tz_offset_seconds();
    let adj = ((secs as i64) + offset).rem_euclid(86400) as u64;
    let h = adj / 3600;
    let m = (adj % 3600) / 60;
    let s = adj % 60;
    format!("{:02}:{:02}:{:02}", h, m, s)
}

fn local_tz_offset_seconds() -> i64 {
    // Parse /etc/timezone + /etc/localtime if possible; otherwise 0 (UTC).
    // Fallback: use the `date +%z` command.
    if let Ok(out) = std::process::Command::new("date").arg("+%z").output() {
        if out.status.success() {
            let s = String::from_utf8_lossy(&out.stdout);
            let s = s.trim();
            if s.len() == 5 {
                let sign: i64 = if &s[0..1] == "-" { -1 } else { 1 };
                let h: i64 = s[1..3].parse().unwrap_or(0);
                let m: i64 = s[3..5].parse().unwrap_or(0);
                return sign * (h * 3600 + m * 60);
            }
        }
    }
    0
}
