/// Very simple YAML extraction of the `shared.pueue_directory` field.
/// Returns None if not found.
pub fn parse_pueue_directory(yaml_content: &str) -> Option<String> {
    let mut in_shared = false;
    let mut shared_indent: Option<usize> = None;
    for raw_line in yaml_content.lines() {
        if raw_line.trim_start().starts_with('#') { continue; }
        let indent = raw_line.len() - raw_line.trim_start().len();
        let line = raw_line.trim();
        if line.is_empty() { continue; }
        if !in_shared {
            if line.starts_with("shared:") {
                in_shared = true;
                shared_indent = Some(indent);
            }
            continue;
        }
        // While in shared block, require deeper indentation.
        let base = shared_indent.unwrap_or(0);
        if indent <= base {
            // Left the shared block.
            in_shared = false;
            continue;
        }
        if let Some(rest) = line.strip_prefix("pueue_directory:") {
            let mut v = rest.trim().to_string();
            // Strip optional quotes.
            if (v.starts_with('"') && v.ends_with('"') && v.len() >= 2) ||
               (v.starts_with('\\'') && v.ends_with('\\'') && v.len() >= 2) {
                v = v[1..v.len()-1].to_string();
            }
            if !v.is_empty() {
                return Some(v);
            }
        }
    }
    None
}
'''
